import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    if k * n % 2 != 0:
        print(-1)
        return

    m = k * n // 2
    matches = []

    for i in range(1, n + 1):
        for j in range(k):
            next_team = (i + j + 1) % n
            if next_team == 0:
                next_team = n
            matches.append((i, next_team))

    print(m)
    for a, b in matches:
        print(a, b)

if __name__ == "__main__":
    main()
